const express = require('express');
const { createHandler } = require('graphql-http/lib/use/express');
const { makeExecutableSchema } = require('@graphql-tools/schema');
const { batchDelegateToSchema } = require('@graphql-tools/batch-delegate');
const db = require('../db');

const app = express();
app.use(express.json());

const resolvers = {
  Query: {
    devices: async (_, { serialNumbers }, context) => {
      // Filter requested serial numbers strictly to those owned by caller's organization
      const allowedDevices = await db('registered_devices')
        .whereIn('serial_number', serialNumbers)
        .andWhere({ organization_id: context.user.organizationId })
        .select('serial_number');

      return allowedDevices.map(d => ({ serialNumber: d.serial_number }));
    }
  },
  Device: {
    liveTelemetry: {
      selectionSet: '{ serialNumber }',
      resolve(device, args, context, info) {
        return batchDelegateToSchema({
          schema: context.telemetrySubschema,
          operation: 'query',
          fieldName: 'telemetryBatch',
          key: device.serialNumber,
          context,
          info
        });
      }
    }
  }
};

const schema = makeExecutableSchema({ typeDefs: require('./telemetryDefs'), resolvers });
app.all('/graphql', createHandler({ schema }));
module.exports = app;
